import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"AI Credits — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Credits — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/ai-credits"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Credits — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/ai-credits"}]]},"headers":[],"relativePath":"developer-guide/ai-credits.md","filePath":"developer-guide/ai-credits.md","lastUpdated":1787957056000}'),r={name:"developer-guide/ai-credits.md"};function s(n,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="ai-credits-—-developer-guide" tabindex="-1">AI Credits — Developer Guide <a class="header-anchor" href="#ai-credits-—-developer-guide" aria-label="Permalink to &quot;AI Credits — Developer Guide&quot;">​</a></h1><p>Platform-billed AI usage is metered through a <strong>dual-balance wallet</strong> per workspace.</p><h2 id="buckets" tabindex="-1">Buckets <a class="header-anchor" href="#buckets" aria-label="Permalink to &quot;Buckets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bucket</th><th>Column</th><th>Source</th><th>Rollover</th></tr></thead><tbody><tr><td><strong>Included</strong></td><td><code>ai_wallets.included_remaining</code></td><td>AI module activation + monthly grant</td><td>Expires unused balance each period</td></tr><tr><td><strong>Prepaid</strong></td><td><code>ai_wallets.prepaid_balance</code></td><td>Credit pack subscriptions (<code>ai-credits-*</code>)</td><td>Never expires on rollover</td></tr></tbody></table><p><code>available = included_remaining + prepaid_balance</code>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Central settings (see <code>SystemSettingDefinitions</code> / <code>SystemSettingsSeeder</code>):</p><table tabindex="0"><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ai_monthly_included_credits</code></td><td>Full-month included grant after rollover / activation refresh</td></tr><tr><td><code>ai_tokens_per_credit</code></td><td>Tokens per burned credit (minimum 1 credit per billable turn)</td></tr></tbody></table><p>Pack sizes map in <code>config/ai-credits.php</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;packs&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;ai-credits-1k&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;ai-credits-5k&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;ai-credits-20k&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><h2 id="lifecycle-events" tabindex="-1">Lifecycle events <a class="header-anchor" href="#lifecycle-events" aria-label="Permalink to &quot;Lifecycle events&quot;">​</a></h2><h3 id="first-ai-module-activation-mid-month" tabindex="-1">First AI module activation (mid-month) <a class="header-anchor" href="#first-ai-module-activation-mid-month" aria-label="Permalink to &quot;First AI module activation (mid-month)&quot;">​</a></h3><p><code>GrantAiCreditsOnModuleActivate</code> calls <code>AiCreditWalletService::proratedIncludedAmount()</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prorated = ceil((days_left / days_in_month) * monthly_included)</span></span></code></pre></div><p>Ledger type: <code>grant_prorated</code>.</p><h3 id="monthly-rollover" tabindex="-1">Monthly rollover <a class="header-anchor" href="#monthly-rollover" aria-label="Permalink to &quot;Monthly rollover&quot;">​</a></h3><p>Command: <code>php artisan ai:rollover-monthly-credits</code></p><p>For each entitled workspace whose <code>period_ym</code> ≠ current UTC <code>Y-m</code>:</p><ol><li>Ledger <code>expire_included</code> for remaining included balance.</li><li>Grant fresh <code>grant_included</code> for <code>ai_monthly_included_credits</code>.</li><li><strong>Prepaid balance unchanged.</strong></li></ol><p>Also available as <code>AiCreditWalletService::ensurePeriod()</code> for request-path catch-up when <code>period_ym</code> is stale. <strong>Wired on</strong> chat, Lead Copilot, and <code>GET /ai/credits</code> (catalog <strong>1.0.1+</strong>). The scheduled command remains the primary monthly job — see <a href="/deployment/ai-production-readiness">production readiness</a>.</p><h3 id="purchase-grant-idempotent" tabindex="-1">Purchase grant (idempotent) <a class="header-anchor" href="#purchase-grant-idempotent" aria-label="Permalink to &quot;Purchase grant (idempotent)&quot;">​</a></h3><p><code>grantPurchase($tenant, $credits, $subscriptionReference)</code> inserts at most <strong>one</strong> <code>grant_purchase</code> row per morph reference (pack subscription). Repeat calls are no-ops.</p><h3 id="burn-order" tabindex="-1">Burn order <a class="header-anchor" href="#burn-order" aria-label="Permalink to &quot;Burn order&quot;">​</a></h3><p><code>burn($tenant, $credits)</code> depletes <strong>included first</strong>, then prepaid, under a wallet <strong><code>lockForUpdate()</code></strong>. Throws <code>InsufficientAiCreditsException</code> when <code>available &lt; credits</code> (HTTP <strong>402</strong> on tenant API).</p><h2 id="api-surface" tabindex="-1">API surface <a class="header-anchor" href="#api-surface" aria-label="Permalink to &quot;API surface&quot;">​</a></h2><p><code>GET /api/tenant/v1/ai/credits</code> (<code>ai.use</code>) returns wallet summary + recent ledger via <code>AiCreditWalletResource</code> (runs <code>ensurePeriod()</code> first).</p><h2 id="gateway-gate" tabindex="-1">Gateway gate <a class="header-anchor" href="#gateway-gate" aria-label="Permalink to &quot;Gateway gate&quot;">​</a></h2><p>When <code>AiConfig::isPlatform()</code>:</p><ul><li>Chat / Lead Copilot run <code>ensurePeriod()</code>, then assert the wallet can cover a <strong>conservative credit ceiling</strong> (prompt token estimate × 1.25 + <code>ai_max_output_tokens</code> + tool buffer) <strong>before</strong> prompting the agent.</li><li>Agent completion tokens are capped via <code>EloSyncBusinessAgent::maxTokens()</code>.</li><li>After the turn, credits burn from actual token usage: <code>ceil(total_tokens / ai_tokens_per_credit)</code> (minimum 1 when tokens &gt; 0).</li></ul><p>BYOK mode skips wallet burn.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p><code>tests/Feature/Tenant/Ai/AiCreditWalletTest.php</code> covers proration, burn order, purchase idempotency, rollover expiration, <code>ensurePeriod</code>, and <code>assertAvailable</code>.</p><p><code>tests/Feature/Tenant/Ai/AiPlatformCreditsGateTest.php</code> asserts HTTP 402, pre-provider ceiling gate, and credits-summary lazy rollover.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><ul><li>Schedule <code>ai:rollover-monthly-credits</code> daily (UTC) — see <code>routes/console.php</code>.</li><li>Monitor <code>ai_usage_events</code> and Central AI usage analytics for operator dashboards.</li></ul>`,35)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
